import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] aLine = br.readLine().split(" ");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(aLine[i]);
        }

        int n1 = n / 2;
        List<Integer> a1 = new ArrayList<>();
        List<Integer> a2 = new ArrayList<>();

        generateSums1(0, 0, a, n1, m, a1);
        generateSums2(n1, 0, a, n, m, a2);

        Set<Integer> setA1 = new HashSet<>(a1);
        List<Integer> uniqueA1 = new ArrayList<>(setA1);
        Collections.sort(uniqueA1);

        int ans = 0;
        for (int i : a2) {
            int j = Collections.binarySearch(uniqueA1, m - i);
            if (j < 0) {
                j = -j - 1;
            }
            if (j > 0) {
                int candidate = uniqueA1.get(j - 1) + i;
                if (candidate > ans) {
                    ans = candidate;
                }
            }
        }
        System.out.println(ans);
    }

    private static void generateSums1(int i, int currentSum, int[] a, int n1, int m, List<Integer> a1) {
        if (i == n1) {
            a1.add(currentSum);
        } else {
            generateSums1(i + 1, (currentSum + a[i]) % m, a, n1, m, a1);
            generateSums1(i + 1, currentSum, a, n1, m, a1);
        }
    }

    private static void generateSums2(int i, int currentSum, int[] a, int n, int m, List<Integer> a2) {
        if (i == n) {
            a2.add(currentSum);
        } else {
            generateSums2(i + 1, (currentSum + a[i]) % m, a, n, m, a2);
            generateSums2(i + 1, currentSum, a, n, m, a2);
        }
    }
}
